async function loadProjects(){try{const projects=await api.get("/projects");document.getElementById("projectsList").innerHTML=projects.map(p=>`\n            <tr>\n                <td class="uid-pill">#${p.project_uid}</td>\n                <td class="font-medium text-main">${p.title}</td>\n                <td>\n                    <div class="progress-container">\n                        <div class="progress-bar" style="width: ${p.current_stage/8*100}%"></div>\n                    </div>\n                    <span class="text-muted" style="font-size: 0.75rem;">Stage D${p.current_stage} Validation</span>\n                </td>\n                <td>\n                    <span class="status-pill ${"Closed"===p.status?"active":"warning"}">\n                        ${p.status}\n                    </span>\n                </td>\n                <td class="text-right">\n                    <button class="btn btn-outline-sm" onclick="window.location.href='/projects/project-details.html?id=${p.id}'">\n                        Manage\n                    </button>\n                </td>\n            </tr>\n        `).join(""),lucide.createIcons()}catch(err){console.error("Fetch error:",err)}}function showCreateModal(){document.getElementById("createModal").style.display="flex"}function hideCreateModal(){document.getElementById("createModal").style.display="none"}document.getElementById("createProjectForm")?.addEventListener("submit",async e=>{e.preventDefault();const title=document.getElementById("projectTitle").value,description=document.getElementById("projectDesc").value;try{await api.post("/projects",{title:title,description:description}),hideCreateModal(),loadProjects()}catch(err){alert(err.message)}}),document.addEventListener("DOMContentLoaded",loadProjects);